/* Home.tsx */
import React from 'react';
import ComputerImage from '../images/computer2-1.png';
import BirdBooks from '../images/bird-books.png';
import ContactImage from '../images/contact-image.png';
import GirlBooks from '../images/girl-books.png';
import ResumeImage from '../images/resume-writing.png';
import Scheduling from '../images/scheduling.png';
import Review from '../components/Review';
import Contact from '../components/Contact';
import NavBar from '../components/NavBar';
import 'tailwindcss/tailwind.css';

const Home: React.FC = () => {
  return (
    <div className="bg-gray-50 min-h-screen">
      <NavBar />
      <div className="space-y-8 px-4 pb-8">
        {/* Hero Section */}
        <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-white shadow-lg rounded-lg p-6">
          <img src={ComputerImage} alt="Olivertutor.me" className="w-full md:w-1/2 rounded-lg" />
          <div className="p-4 space-y-4">
            <h1 className="text-4xl font-bold text-blue-600">Enhance Your Career With Confidence</h1>
            <p className="text-gray-700">
              Join me on this exciting journey into AI and Python. Let's not just learn,
              but innovate, explore, and lead the future together.
            </p>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-md shadow hover:bg-blue-700">Book Tutoring</button>
          </div>
        </div>

        {/* Reviews Section */}
        <section className="space-y-4 bg-white shadow-lg rounded-lg p-6">
          <h2 className="text-2xl font-bold text-blue-600">Reviews</h2>
          <Review reviewer="John Doe" review="Great tutor! Highly recommended." />
        </section>

        {/* About Oliver Section */}
        <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-white shadow-lg rounded-lg p-6">
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold text-blue-600">About Oliver</h2>
            <p className="text-gray-700">
              Hi, I'm Oliver! I am here to guide you through the fascinating fields of Data Science,
              including the latest in AI and Python development. As a senior Biology student,
              I started the journey into AI and programming from scratch. I know how daunting and
              intimidating these complex topics can be.
            </p>
          </div>
          <img src={ResumeImage} alt="Oliver's Resume" className="w-full md:w-1/2 rounded-lg" />
        </div>

        {/* Portfolio Section */}
        <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-white shadow-lg rounded-lg p-6">
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold text-blue-600">Portfolio</h2>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-md shadow hover:bg-blue-700">Portfolio Coming Soon</button>
          </div>
          <img src={BirdBooks} alt="Portfolio" className="w-full md:w-1/2 rounded-lg" />
        </div>

        {/* Blog Section */}
        <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-white shadow-lg rounded-lg p-6">
          <img src={GirlBooks} alt="Blog" className="w-full md:w-1/2 rounded-lg" />
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold text-blue-600">Blog</h2>
            <button className="bg-gray-500 text-white px-4 py-2 rounded-md shadow hover:bg-gray-700">Blog Coming Soon</button>
          </div>
        </div>

        {/* Schedule a Session Section */}
        <div className="flex flex-col md:flex-row items-center space-y-4 md:space-y-0 bg-white shadow-lg rounded-lg p-6">
          <div className="flex-1 space-y-4 p-4">
            <h2 className="text-2xl font-bold text-blue-600">Schedule a Session</h2>
            <button className="bg-blue-600 text-white px-4 py-2 rounded-md shadow hover:bg-blue-700">Book Tutoring</button>
          </div>
          <img src={Scheduling} alt="Scheduling" className="w-full md:w-1/2 rounded-lg" />
        </div>

        <section className="bg-white shadow-lg rounded-lg p-6">
          <Contact />
        </section>
      </div>
    </div>
  );
};

export default Home;
